import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
answers = []

def add(number, xml, reason, notes, removed=None, benefit=None, repeal=None):
    source = sources[len(answers)]
    assert source['number'] == number
    item = {key: source[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}
    item.update(proposed_xml=xml.strip(), reason=reason, review_notes=notes, status='rewrite_draft')
    if removed:
        item.update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)
    if repeal:
        item.update(change_type='full_repeal', repeal_policy_id='editorial_direction_2026_10_19', repeal_scope=repeal)
    if benefit:
        item['benefit_review'] = benefit
    assert not source.get('benefit_check_required') or len(item.get('benefit_review', '')) >= 100
    answers.append(item)

add('324 S', '''
<p>Dans les immeubles collectifs, le correctif d'ensemble appliqué à la surface pondérée comparative de la partie principale est ajusté, s'il y a lieu, selon le niveau du local et la présence ou l'absence d'ascenseur, conformément au barème suivant :</p>
<table><tbody>
<tr><th rowspan="2">NIVEAU DU LOCAL</th><th colspan="2">COEFFICIENT</th></tr>
<tr><th>Immeuble avec ascenseur</th><th>Immeuble sans ascenseur</th></tr>
<tr><td>6e et au-dessus</td><td>0</td><td>- 0,15</td></tr>
<tr><td>5e</td><td>0</td><td>- 0,10</td></tr>
<tr><td>4e</td><td>0</td><td>- 0,05</td></tr>
<tr><td>3e</td><td>0</td><td>0</td></tr>
<tr><td>2e</td><td>0</td><td>0</td></tr>
<tr><td>1er</td><td>0</td><td>0</td></tr>
<tr><td>Rez-de-chaussée</td><td>0</td><td>0</td></tr>
</tbody></table>
<p>Pour l'application de ce coefficient, l'entresol compte pour un étage.</p>
<p>La présence d'un ascenseur n'entraîne aucune majoration de la surface. Les tarifs prévus à l'article 324 K ne sont pas recalculés à la hausse du seul fait de la suppression des coefficients positifs du présent article.</p>
<p>Cette suppression s'applique aux impositions établies au titre des années commençant à compter du 1er janvier de l'année suivant celle de l'entrée en vigueur de la loi portant la présente réforme. Les impositions des années antérieures, leurs dégrèvements, restitutions, prescriptions et recours restent régis par les règles applicables à ces années.</p>
''',
    "Réforme de fond : suppression du supplément de coefficient de + 0,05 lié à l'ascenseur, du deuxième au sixième étage et au-delà. Ce supplément d'assiette n'est pas une condition de sécurité ou d'accessibilité de l'équipement. Maintien intégral des minorations pour absence d'ascenseur, des niveaux du barème et du décompte de l'entresol. La rédaction rend les deux colonnes explicites et interdit une neutralisation mécanique par le tarif.",
    "Barème source relu en entier : sept niveaux ; minorations conservées de - 0,15, - 0,10 et - 0,05 respectivement au sixième étage et au-delà, au cinquième et au quatrième. Renvois vérifiés dans 324 P, 324 K et 324 W ; leur chaîne de calcul doit appliquer le nouveau barème sans reconstituer le supplément par recalcul du tarif. La règle de non-relèvement figure dans le texte proposé ; coordonner expressément 324 K hors de ce lot. L'allègement porte sur les années nouvelles, sans remboursement général des années anciennes ni compensation fiscale inventée.",
    removed=["Majoration de + 0,05 du correctif d'ensemble pour les locaux avec ascenseur situés au deuxième étage et au-dessus."])

add('324 T', '''
<p>I. - La surface pondérée totale de la partie principale est égale à sa surface pondérée nette. Aucun élément d'équipement n'entraîne l'ajout d'une surface représentative à cette surface.</p>
<p>II. - Lorsqu'un local est affecté à la fois à l'habitation et à un usage professionnel, aucune surface représentative d'un élément d'équipement n'est ajoutée pour l'évaluation de la partie affectée à l'habitation.</p>
<p>Les tarifs prévus à l'article 324 K ne sont pas recalculés à la hausse du seul fait de la suppression des équivalences superficielles du présent article.</p>
<p>Cette suppression s'applique aux impositions établies au titre des années commençant à compter du 1er janvier de l'année suivant celle de l'entrée en vigueur de la loi portant la présente réforme. Les impositions des années antérieures, leurs dégrèvements, restitutions, prescriptions et recours restent régis par les règles applicables à ces années.</p>
''',
    "Réforme de fond : retrait de toutes les surfaces fictives ajoutées pour les équipements de la partie principale. Le maintien de ces suppléments pour l'eau, l'électricité, l'assainissement ou le chauffage augmente l'assiette sans protéger leur fonctionnement ni leur sécurité. Le I conserve la définition complète de la surface totale et le II couvre expressément les locaux mixtes ; la répartition proportionnelle d'un supplément désormais nul disparaît. Aucun équipement ni son usage n'est interdit ou soumis à une nouvelle pièce.",
    "Lecture complète du barème : eau 4 m² ; gaz et électricité 2 m² chacun ; baignoire 5 ; douche ou bac à laver 4 ; lavabo ou autre appareil 3 ; WC particulier 3 par unité ; égout 3 par local ; vide-ordures 3 ; chauffage central 2 par pièce et annexe d'hygiène. Tous ces ajouts sont effectivement supprimés, y compris leurs variantes collectives ; leurs chiffres ne sont pas des taux fiscaux à remplacer. Les surfaces et correctifs antérieurs au stade net demeurent régis par 324 L à 324 S. 324 K, 324 W, 324 X et les supports déclaratifs doivent être coordonnés avec la non-reconstitution tarifaire expressément prévue ici. Aucun changement du champ professionnel de 1498 ou des normes de salubrité.",
    removed=[
        "Barème complet des équivalences superficielles des équipements de la partie principale et ajout de ces surfaces à la surface pondérée nette.",
        "Calcul proportionnel des équivalences d'équipement pour la partie d'habitation d'un local à usage mixte, rendu sans objet par leur suppression."
    ])

add('324 U', '''
<p>I. - La surface pondérée nette des dépendances bâties et des éléments bâtis formant dépendances est calculée en appliquant le correctif d'ensemble prévu à l'article 324 P à leur surface réelle ou, pour les éléments visés à l'article 324 N, à leur surface pondérée brute.</p>
<p>Le résultat est arrondi au mètre carré inférieur.</p>
<p>II. - La surface pondérée de ces dépendances et éléments bâtis est égale à leur surface pondérée nette. Aucune surface représentative d'un élément d'équipement n'y est ajoutée, y compris lorsqu'ils font l'objet d'une évaluation distincte.</p>
<p>Les tarifs prévus à l'article 324 K ne sont pas recalculés à la hausse du seul fait de la suppression des équivalences superficielles du présent article.</p>
<p>Cette suppression s'applique aux impositions établies au titre des années commençant à compter du 1er janvier de l'année suivant celle de l'entrée en vigueur de la loi portant la présente réforme. Les impositions des années antérieures, leurs dégrèvements, restitutions, prescriptions et recours restent régis par les règles applicables à ces années.</p>
''',
    "Réforme de fond : suppression des suppléments d'assiette pour les équipements des dépendances, sans retrait de la pondération de leur surface réelle. Le I et son arrondi favorable sont maintenus et rendus plus lisibles. Le II définit entièrement la nouvelle surface, égale à la surface nette, pour les dépendances évaluées ensemble ou séparément. Aucune fonction de sécurité ne dépend de ces surfaces fiscales ajoutées.",
    "Sont retirés les ajouts source de 5 m² par baignoire, 4 par receveur de douches et bac à laver, 3 par lavabo et autre appareil sanitaire, 3 par WC particulier, 2 par pièce et annexe d'hygiène chauffée ; ainsi que, pour les seules évaluations distinctes, 2 m² d'eau et 2 m² d'électricité. La distinction de champ de ces deux derniers ajouts a été lue et n'est pas étendue aux années antérieures. Les renvois 324 N et 324 P, lus intégralement, conservent notamment les pondérations et l'arrondi inférieur ; 324 V additionne désormais les surfaces sans équipements. Coordonner 324 K hors lot pour empêcher la neutralisation tarifaire interdite par le texte proposé.",
    removed=[
        "Barème et ajouts de surfaces représentatives des équipements sanitaires et du chauffage central des dépendances bâties et éléments assimilés.",
        "Ajouts spécifiques de deux mètres carrés pour l'eau et de deux mètres carrés pour l'électricité en cas d'évaluation distincte d'une dépendance."
    ])

add('324 V', '''
<p>I. - La surface pondérée totale d'une propriété ou d'une fraction de propriété est la somme de la surface pondérée totale de sa partie principale et des surfaces pondérées de ses dépendances bâties et de ses éléments bâtis formant dépendances.</p>
<p>II. - La surface pondérée totale des pièces indépendantes situées dans les immeubles collectifs et celle des éléments visés au II de l'article 324 G font, dans tous les cas, l'objet d'un décompte distinct permettant d'individualiser leur calcul.</p>
''',
    "Réécriture à droit constant de la somme des surfaces et du calcul individualisé des éléments évalués séparément. Le décompte distinct de la source assure la traçabilité de chaque valeur ; il ne suffit pas à prouver l'existence d'un formulaire ou dépôt administratif séparé. Il n'est donc pas présenté comme une charge effectivement abrogée. Les dépôts multiples expressément imposés sont, eux, supprimés dans 324 AI, sans fusionner les unités d'évaluation.",
    "Le II de 324 G a été lu : il vise les dépendances à évaluation distincte en raison de leur nature particulière, notamment les éléments de pur agrément, garages et emplacements individuels de stationnement dans les immeubles collectifs. Leur calcul distinct demeure nécessaire. La somme du I ne doit pas compter deux fois un même élément. Le décompte individualisé n'interdit pas de réunir les renseignements dans le dépôt de 324 AI et n'impose pas une nouvelle déclaration. Coordination avec 324 T et 324 U pour les surfaces nouvelles sans équivalences d'équipement ; leurs transitions fiscales s'appliquent aux données additionnées.")

add('324 W', '''
<p>Sous réserve de l'harmonisation prévue au deuxième alinéa du I de l'article 1503 du code général des impôts, la valeur locative des locaux de référence mentionnés à l'article 324 J est calculée en multipliant leur surface pondérée totale, déterminée conformément aux articles 324 L à 324 V, par le tarif correspondant, établi dans les conditions de l'article 324 K.</p>
''',
    "Réécriture à droit constant de la règle de calcul, en exprimant directement la multiplication de la surface par le tarif. Le renvoi à l'ensemble des articles de surface intègre les réductions proposées en 324 S, 324 T et 324 U. Cet article ne crée ni prélèvement autonome ni formalité susceptible d'être retirée sans priver les évaluations de leur règle de calcul ; l'harmonisation et la référence au tarif restent nécessaires.",
    "324 J, 324 K et CGI 1503 ont été lus intégralement, notes comprises : choix de locaux représentatifs, tarifs et harmonisation communale ne sont pas assimilés à une taxe nouvelle. Le renvoi demeure précisément au deuxième alinéa du I de 1503. Appliquer les dispositions de non-relèvement tarifaire et les transitions fiscales expressément inscrites en 324 S, 324 T et 324 U ; ne pas recalculer les tarifs à la hausse à seule fin de compenser les surfaces retirées. La coordination explicite de 324 K hors lot reste à porter dans son texte.")

add('324 X', '''
<p>I. - Pour leur évaluation, les locaux d'habitation autres que les locaux de référence sont classés par comparaison avec les locaux de référence qui représentent les différentes catégories existantes.</p>
<p>II. - Dans une même catégorie, la valeur locative cadastrale de chaque local est déterminée par comparaison avec celle du ou des locaux choisis pour représenter cette catégorie, en respectant l'égalité proportionnelle des évaluations.</p>
<p>Pour chaque local, la comparaison tient compte des suppressions de majorations et d'équivalences superficielles prévues aux articles 324 S, 324 T et 324 U. Leur seule application ne peut entraîner une hausse de sa valeur locative ni rétablir, par la comparaison, une majoration ou une équivalence supprimée.</p>
<p>Le précédent alinéa s'applique aux mêmes années d'imposition que les suppressions auxquelles il se rapporte. Les droits, restitutions, prescriptions et recours relatifs aux années antérieures demeurent régis par les règles applicables à ces années.</p>
''',
    "Clarification à droit constant du classement et de l'égalité proportionnelle. Réforme de coordination : la comparaison ne doit pas réintroduire les suppléments retirés en 324 S à 324 U ni augmenter une valeur par le seul changement de surface du local de référence. La garantie s'applique à chaque local comparé et aux mêmes années que l'allègement ; aucun classement général ni tarif nouveau n'est inventé.",
    "Renvois contrôlés avec 324 J, 324 K et 324 W : les locaux de référence demeurent les termes de comparaison. La protection ajoutée vise seulement les effets de la suppression des suppléments, sans figer les autres variations légalement fondées de consistance ou de tarif. Une modification de 324 K hors lot doit expliciter la non-neutralisation des réductions. Cette coordination ne supprime aucun coefficient réducteur ni exonération et ne transforme pas les règles professionnelles de 1498 en règles d'habitation.",
    removed=["Réintégration des suppléments cadastraux supprimés ou hausse de valeur par le seul effet de leur retrait dans le mécanisme de comparaison aux locaux de référence."])

add('324 Y', '''
<p>Lorsqu'un bail écrit ou une location verbale mentionné à l'article 324 C porte sur un local dont les parties ont des affectations différentes, la partie affectée à l'habitation est évaluée selon les articles 324 D à 324 X. La valeur locative ainsi déterminée est déduite du montant global du bail ou de la location pour calculer la valeur locative du reste du local.</p>
<p>Pour cette déduction, la valeur de la partie affectée à l'habitation est déterminée sans tenir compte des seules suppressions de majorations et d'équivalences superficielles prévues aux articles 324 S, 324 T et 324 U lorsque leur prise en compte augmenterait la valeur locative du reste du local. Cette règle ne rétablit aucun supplément pour l'imposition de la partie affectée à l'habitation.</p>
<p>Le précédent alinéa s'applique aux mêmes années d'imposition que les suppressions auxquelles il se rapporte. Les impositions des années antérieures, leurs restitutions, prescriptions et recours restent régis par les règles applicables à ces années.</p>
''',
    "Clarification à droit constant du calcul par déduction de la part d'habitation du loyer global. Réforme de coordination : une diminution de cette part due aux suppressions de 324 S à 324 U ne doit pas augmenter la valeur résiduelle professionnelle. Pour ce seul calcul résiduel, la valeur imputée est donc calculée sans ces suppressions lorsqu'elles produiraient cet effet. L'habitation bénéficie de sa réduction propre ; aucun supplément n'est rétabli sur elle. Il n'est créé ni déclaration séparée ni justificatif supplémentaire.",
    "324 C a été lu intégralement : baux et locations verbales en cours à la date de référence, prix normaux et corrections du loyer. CGI 1498 a aussi été lu : le renvoi historique aux baux ne remplace pas son régime professionnel révisé. La nouvelle règle empêche explicitement l'extension mécanique de l'assiette résiduelle par l'allègement de la part d'habitation ; son calcul conserve toutes les autres caractéristiques et variations applicables au local, sans figer une valeur historique arbitraire. Le dépôt unique de 324 AI ne fusionne pas les évaluations. Maintien du champ temporel propre des méthodes auxquelles cet article reste applicable, avec la même transition que 324 S à 324 U pour l'allègement ajouté.",
    removed=["Augmentation mécanique de la valeur locative résiduelle du surplus professionnel d'un local mixte du seul fait du retrait des suppléments de la partie d'habitation."])

add('324 Z', '''
<p>Pour l'application du C du II de l'article 1498 du code général des impôts, la surface pondérée d'un local est la somme des superficies de ses différentes parties, après application, s'il y a lieu, du coefficient prévu au troisième alinéa. Cette somme est, le cas échéant, arrondie au mètre carré inférieur.</p>
<p>Pour chaque partie du local, y compris les dégagements et les sanitaires, la superficie retenue est la superficie réelle mesurée au sol, entre les murs ou les séparations, puis arrondie au mètre carré inférieur.</p>
<p>Lorsqu'une partie du local a une valeur d'utilisation réduite par rapport à son affectation principale, sa superficie est réduite par un coefficient de 0,5 si elle est couverte et de 0,2 si elle ne l'est pas.</p>
''',
    "Réécriture à droit constant des trois étapes : mesure de chaque partie, pondération des surfaces de moindre utilisation, puis somme. Les deux coefficients réduits et les deux niveaux d'arrondi inférieur sont conservés. Il s'agit de paramètres favorables d'une assiette maintenue, non de prélèvements ou de formalités autonomes à abroger ; aucune nouvelle obligation de mesurage certifié n'est ajoutée.",
    "CGI 1498, notamment le C du II, a été lu intégralement avec sa note. Contrôle : 0,5 pour une partie couverte de moindre valeur d'utilisation, 0,2 pour une partie non couverte ; les dégagements et sanitaires restent inclus dans la mesure réelle. Trois alinéas conservés, afin que le renvoi interne au troisième alinéa reste exact. L'arrondi par partie précède celui de la somme ; ne pas remplacer ces arrondis par un arrondi supérieur ou par un seul arrondi final. Les réductions restent ouvertes aux futurs locaux éligibles.")

add('324 AA', '''
<p>I. - Pour l'évaluation prévue à l'article 1498 du code général des impôts, les locaux qui remplissent toutes les conditions suivantes sont assimilés à des terrains à usage commercial ou industriel et classés dans la catégorie 1 du sous-groupe III définie à l'article 310 Q de l'annexe II au même code :</p>
<p>1° Ils sont classés dans la catégorie 5 du sous-groupe I définie au même article 310 Q ;</p>
<p>2° Leur surface extérieure non couverte utilisée pour la vente de produits d'origine agricole excède 50 % de leur surface totale. La surface totale est la somme des surfaces intérieures et extérieures, couvertes ou non. Les surfaces retenues au présent 2° sont les surfaces non pondérées utilisées pour une activité correspondant à l'affectation principale du local, appréciée au regard de sa catégorie de classement ;</p>
<p>3° La vente de produits d'origine agricole représente plus de la moitié du chiffre d'affaires total de l'établissement auquel le local est affecté. Le chiffre d'affaires retenu est celui réalisé hors taxes pendant l'année civile précédant l'année d'imposition.</p>
<p>Pour l'application des 2° et 3°, la vente de produits d'origine agricole s'entend de la vente de fleurs, de plantes, de graines, d'aliments pour animaux de compagnie, d'engrais et de produits phytosanitaires.</p>
<p>II. - L'application du classement prévu au I dépend des conditions qui y sont définies et n'est pas subordonnée à une notification de l'entreprise au propriétaire. L'entreprise qui exploite le bien sans en être propriétaire n'est pas tenue, sur le fondement du présent article, d'informer celui-ci de la première réalisation de ces conditions ou de leur cessation.</p>
<p>Le II s'applique à compter de l'entrée en vigueur de la loi portant la présente réforme, y compris pour l'examen d'un classement encore en cours. Il ne dispense pas des obligations fiscales autonomes légalement applicables au propriétaire, mais aucun défaut de notification au titre du présent II ne peut, à lui seul, faire obstacle au classement d'un bien remplissant les conditions du I.</p>
''',
    "Maintien et clarification de l'assimilation favorable des très grandes surfaces de vente agricole aux terrains commerciaux ou industriels, avec toutes ses conditions cumulatives. Réforme de fond au II : suppression de la notification obligatoire au propriétaire au plus tard le 31 décembre, tant à l'entrée qu'à la sortie des conditions. Aucune déclaration de remplacement n'est créée ; le classement reste fondé sur les caractéristiques et le chiffre d'affaires réels, pour les biens futurs aussi.",
    "Contrôles : surface extérieure non couverte strictement supérieure à 50 %, surfaces non pondérées correspondant à l'affectation principale ; chiffre d'affaires agricole strictement supérieur à la moitié du total, hors taxes, année civile précédente ; six familles de produits conservées. CGI 1498 et annexe II 310 Q ont été lus intégralement avec leurs notes : catégories 5/I et 1/III conservées. 310 Q présente un recouvrement rédactionnel au seuil de 2 500 m² entre la catégorie 4/I, surface comprise entre 400 et 2 500, et la catégorie 5/I, surface supérieure ou égale à 2 500 ; cette discordance préexistante n'est pas corrigée silencieusement et l'exigence de classement en 5/I demeure. La note source impose aux propriétaires éligibles au 1er janvier 2026 une déclaration avant le 1er septembre 2026, sur le fondement de l'article 2 du décret n° 2026-804 : cette obligation extérieure n'est pas abrogée par le présent II et doit être examinée séparément, notamment avec CGI 1406. Aucune fermeture de l'avantage aux nouvelles opérations.",
    removed=[
        "Notification obligatoire au propriétaire, avant le 31 décembre, de la première réalisation des conditions par l'entreprise qui exploite le bien sans en être propriétaire.",
        "Notification obligatoire au propriétaire, avant le 31 décembre, de la cessation des conditions par cette même entreprise."
    ])

add('324 AE', '''
<p>Le prix de revient mentionné à l'article 1499 du code général des impôts est la valeur d'origine à laquelle les immobilisations doivent être inscrites au bilan conformément à l'article 38 quinquies.</p>
<p>Cette valeur n'est pas rectifiée au titre des taxes sur le chiffre d'affaires, notamment de la taxe sur la valeur ajoutée, supportées par l'entreprise.</p>
<p>La valeur d'origine retenue est le prix de revient intégral, avant les déductions exceptionnelles et les amortissements spéciaux autorisés en matière fiscale. Cette règle s'applique également aux immobilisations partiellement réévaluées ou amorties en tout ou partie.</p>
''',
    "Réécriture à droit constant : distinction explicite de la valeur d'origine, de l'absence de rectification pour les taxes sur le chiffre d'affaires et du traitement des déductions et amortissements fiscaux. L'article ne prélève pas une TVA supplémentaire et ne supprime pas les déductions pour l'impôt sur les bénéfices ; il précise le prix de revient imposé par 1499. Sa suppression isolée laisserait cette assiette sans définition, sans abolir la taxe foncière industrielle. Les justificatifs redondants sont retirés dans 324 AF plutôt que par une disparition ambiguë de cette valeur.",
    "CGI 1499 a été lu en entier avec ses notes : taux d'intérêt de 4 % et 6 %, abattements de 25 % et 33,33 %, déduction complémentaire liée à certaines catégories d'établissements et renvois aux articles 21 de l'annexe III et 310 K de l'annexe II demeurent distincts. Aucun de ces avantages ni leur application future n'est supprimé ici. Le renvoi normatif à 38 quinquies est conservé, sans prétendre réécrire sa définition comptable. Ne pas confondre absence de correction de TVA et interdiction de la déduire dans son régime propre, ni prix de revient cadastral et bénéfice soumis au nouvel IS à la distribution.")

add('324 AF', '''
<p>Lorsque le bilan ne permet pas de déterminer le prix de revient, celui-ci est établi, dans la mesure nécessaire, à partir des documents comptables ou de toute autre pièce justificative. À défaut d'éléments suffisants, il est déterminé par voie d'évaluation, sous réserve du droit de contrôle de l'administration.</p>
<p>Les documents et renseignements exacts, suffisamment identifiés et légalement détenus par l'administration sous une forme exploitable sont réutilisés. Ils ne peuvent être demandés de nouveau au seul motif qu'ils n'ont pas été joints à la procédure en cours ou présentés sur un support particulier. Aucun état récapitulatif ni aucune attestation reproduisant exclusivement ces éléments n'est exigé sur le fondement du présent article. Les renseignements manquants ou les rectifications nécessaires peuvent être demandés dans les conditions légales du contrôle.</p>
<p>Le précédent alinéa s'applique aux demandes de pièces adressées à compter de l'entrée en vigueur de la loi portant la présente réforme, y compris dans les procédures en cours. Il ne modifie ni les règles d'assiette des années antérieures, ni leurs prescriptions et voies de recours.</p>
''',
    "Clarification de l'ordre des preuves : bilan, pièces ordinaires puis évaluation à défaut. Réforme de fond : interdiction de réclamer à nouveau des données déjà légalement disponibles et de les faire recopier dans une attestation ou un état spécial. La justification du prix de revient et le contrôle restent possibles sur les éléments manquants ou inexacts ; aucune nouvelle certification ne remplace les doubles pièces.",
    "La priorité du bilan et la faculté de recourir à tous documents, puis à l'évaluation, sont conservées. Articulation avec 324 AE, 324 AG et le II de CGI 1502, lu intégralement : le droit légal de demander des inventaires et pièces utiles subsiste ; la limitation des demandes répétées doit être portée expressément dans 1502 II pour sécuriser sa portée législative. Le réemploi suppose une détention licite et des données exploitables, sans ouvrir un accès à des données protégées détenues par un tiers ni créer un registre de remplacement.",
    removed=["Remise répétée de documents déjà légalement exploitables par l'administration et production d'états ou attestations qui ne feraient que recopier ces mêmes éléments."])

add('324 AG', '''
<p>L'année retenue pour déterminer le prix de revient est celle de la création ou de l'acquisition de l'immobilisation.</p>
<p>Si l'exercice comptable ne coïncide pas avec l'année civile et que la date exacte de l'acquisition ou de la création n'est pas connue, l'année retenue est celle de la clôture de cet exercice.</p>
<p>Lorsque l'année d'acquisition de certaines immobilisations est inconnue, ou que les dépenses relatives aux immobilisations créées ne peuvent pas être ventilées année par année, la référence retenue est la période pendant laquelle ces immobilisations ont été acquises ou créées. Le coefficient de réévaluation est alors égal à la somme des coefficients des années comprises dans cette période, divisée par le nombre de ces années. Cette méthode s'applique notamment aux immobilisations édifiées ou créées par l'entreprise lorsque les dépenses correspondantes se sont étendues sur plusieurs années.</p>
''',
    "Réécriture à droit constant en séparant la règle de l'année exacte, la solution en cas d'exercice décalé et la moyenne sur une période. Les deux solutions subsidiaires évitent de rendre impossible une évaluation faute de date ou de ventilation annuelle ; elles ne sont pas supprimées sous couvert de retirer des obligations. L'article n'exige aucun agrément, relevé supplémentaire ou reconstitution documentaire impossible.",
    "Conservation des trois alinéas, de leurs conditions alternatives et de la formule : somme des coefficients de toutes les années de la période divisée par leur nombre. Ne pas substituer l'année médiane, le seul dernier coefficient ou une moyenne pondérée inventée. CGI 1499 maintient la réévaluation du prix de revient ; les règles de preuve de 324 AF permettent d'employer les pièces ordinaires et d'éviter leurs doubles remises. Aucune période historique n'est effacée et aucun coefficient de réévaluation nouveau n'est créé.")

add('324 AH', '''
<p>I. - Dans le champ défini à l'article 1502 du code général des impôts, les déclarations de révision des évaluations sont souscrites par les redevables de la taxe foncière sur les propriétés bâties désignés à l'article 1400 du même code.</p>
<p>II. - Lorsque les biens d'un établissement industriel appartiennent à plusieurs personnes, chacune répond aux obligations de l'article 1502 pour l'ensemble des seuls éléments imposables dont elle est propriétaire. Un dépôt regroupé dans les conditions de l'article 324 AI ne modifie pas cette répartition et ne crée aucune solidarité entre elles.</p>
<p>Pour les déclarations du présent article, les renseignements exacts, actualisés à la date de référence applicable, suffisamment identifiés et déjà légalement détenus par l'administration sous une forme exploitable ne sont pas transmis de nouveau. Le redevable ne fournit que les éléments nécessaires manquants et les rectifications. Lorsque l'ensemble des renseignements nécessaires est déjà disponible dans ces conditions, aucun dépôt ni aucune confirmation de leur absence de changement n'est exigé.</p>
<p>Le précédent alinéa s'applique aux obligations dont l'échéance intervient à compter de l'entrée en vigueur de la loi portant la présente réforme, ainsi qu'aux demandes de transmission ou de régularisation adressées après cette date dans les procédures en cours. Il ne modifie pas les règles d'assiette des impositions antérieures, leurs restitutions, prescriptions et recours.</p>
''',
    "Maintien à droit constant de l'identité des débiteurs et de la répartition des biens industriels entre propriétaires. Réforme de fond : suppression des déclarations répétant intégralement des données exactes déjà détenues ; les dépôts partiellement nécessaires se limitent aux lacunes et rectifications, sans confirmation négative de remplacement. La dispense ne retire aucune exonération ni l'exclusion légale de certains locaux du champ de la révision.",
    "CGI 1400 et 1502 ont été lus intégralement : ne pas remplacer tous les débiteurs de 1400 par les seuls propriétaires ordinaires ; conserver l'exclusion de 1502 I visant les biens du I de 1498. Le II reste limité aux éléments dont chaque personne est propriétaire et n'ajoute pas de solidarité. La dispense de dépôt lorsque toutes les données sont disponibles exige une coordination expresse de CGI 1502 I, dont l'obligation législative générale ne peut être neutralisée par le seul décret. Le texte proposé formule cette réduction pour le projet de loi ; elle n'est pas présentée comme déjà intégrée à 1502. Les échéances et droits d'autres impôts ne sont pas supprimés.",
    removed=[
        "Nouvelle déclaration ou confirmation sans changement lorsque tous les renseignements nécessaires à la révision sont déjà légalement disponibles, exacts et exploitables.",
        "Répétition dans une déclaration de révision des renseignements déjà disponibles lorsque seuls des compléments ou des rectifications sont nécessaires."
    ])

add('324 AI', '''
<p>I. - Sous réserve des dispenses et du réemploi des données prévus à l'article 324 AH, les déclarations de l'article 1502 du code général des impôts peuvent être réunies dans un même dépôt. Les renseignements nécessaires sont identifiables selon les règles suivantes, sans formulaire ni dépôt distinct pour chaque catégorie :</p>
<p>a. Les renseignements sont distingués par propriété ou fraction de propriété au sens de l'article 324 A, à l'exception des biens réservés à l'usage commun des occupants d'un immeuble collectif ou d'un ensemble immobilier, qui relèvent du récapitulatif prévu au b ;</p>
<p>b. Pour les immeubles collectifs et les ensembles immobiliers, les renseignements récapitulatifs sont regroupés :</p>
<p>Par bâtiment principal, les constructions accessoires qui ne dépendent pas d'un bâtiment principal déterminé étant rattachées au premier de ces bâtiments ;</p>
<p>Par construction accessoire, lorsque l'immeuble collectif ne comporte aucun bâtiment principal auquel la rattacher.</p>
<p>II. - Dans les immeubles collectifs soumis au régime de la copropriété ou appartenant à une société civile immobilière dont l'objet est visé à l'article 1655 ter du code général des impôts, les renseignements propres à chacun des locaux des services communs faisant l'objet d'une occupation distincte, tels que la loge du concierge ou le bureau du syndic, et les renseignements récapitulatifs du I sont fournis, selon le cas, par le syndic de copropriété ou par la société. Ils peuvent figurer dans le même dépôt, sans déclaration particulière séparée.</p>
<p>III. - Lorsqu'une propriété ou fraction de propriété normalement destinée à une utilisation distincte, autre qu'un établissement industriel, est affectée pour partie à l'habitation et pour le reste à un autre usage, les renseignements propres à chacune de ces parties sont distingués dans le même dépôt. Deux déclarations séparées ne sont pas exigées.</p>
<p>IV. - Lorsqu'un établissement industriel comprend des locaux affectés à l'habitation, les renseignements propres à chacun d'eux sont individualisés dans le dépôt, sans déclaration particulière séparée.</p>
<p>Un dépôt peut réunir les renseignements relevant de plusieurs personnes tenues de déclarer dès lors que les éléments relevant de chacune sont identifiables. Ce regroupement ne modifie ni leur qualité, ni leur responsabilité propre. Il n'impose aucune nouvelle collecte de données déjà légalement disponibles dans les conditions de l'article 324 AH.</p>
<p>Le présent article s'applique aux dépôts et aux demandes de régularisation effectués à compter de l'entrée en vigueur de la loi portant la présente réforme, y compris dans les procédures en cours. Les informations déjà reçues ne sont pas déposées de nouveau pour être regroupées ; les droits attachés aux déclarations antérieures restent préservés.</p>
''',
    "Réforme de fond : un même dépôt peut porter les informations des locaux, le récapitulatif de l'immeuble, les services communs, les usages mixtes et les logements d'un établissement industriel. Sont supprimés les formulaires et dépôts obligatoirement distincts, avec maintien des subdivisions I a et b, II, III et IV et des données permettant chaque évaluation. Le regroupement reste une faculté et n'instaure ni mandataire obligatoire ni responsabilité solidaire.",
    "324 A a été lu en entier : propriété, fraction, usage commun et immeuble collectif ne sont pas redéfinis. Sont conservés le rattachement des constructions accessoires au premier bâtiment, la solution sans bâtiment principal, les compétences du syndic ou de la société et l'exclusion des établissements industriels au III. Le IV conserve l'identification de chaque logement, sans confondre durée d'occupation et unité fiscale. Articulation avec CGI 1502, 1655 ter, 324 AH et le modèle facultatif de 324 AJ ; les règles législatives de débiteur et d'assiette demeurent distinctes. Les regroupements n'entraînent aucun nouveau dépôt rétroactif.",
    removed=[
        "Déclaration séparée obligatoire par propriété ou fraction de propriété et déclaration récapitulative matériellement distincte par bâtiment ou construction accessoire.",
        "Déclaration particulière séparée de chaque local des services communs occupé distinctement, en plus du récapitulatif de l'immeuble collectif.",
        "Double déclaration obligatoire pour les parties d'habitation et d'autre usage d'une même propriété ou fraction de propriété non industrielle.",
        "Déclaration particulière matériellement séparée pour chacun des locaux d'habitation compris dans un établissement industriel."
    ])

add('324 AJ', '''
<p>La direction générale des finances publiques met un modèle de déclaration à la disposition des personnes tenues de déclarer. Son utilisation est facultative. Les renseignements légalement nécessaires peuvent être fournis par tout écrit, sur papier ou par une voie électronique légalement ouverte, permettant leur exploitation et le regroupement prévu à l'article 324 AI.</p>
<p>Une déclaration contenant ces renseignements ne peut être refusée et aucun nouveau dépôt ne peut être imposé au seul motif qu'elle n'utilise pas le modèle administratif. Les données réemployées dans les conditions de l'article 324 AH ne sont pas reproduites dans un formulaire.</p>
<p>Ces dispositions s'appliquent aux déclarations et aux demandes de régularisation à compter de l'entrée en vigueur de la loi portant la présente réforme, y compris dans les procédures en cours. Elles n'imposent pas de refaire une déclaration déjà reçue et ne modifient pas les règles d'assiette, les prescriptions ou les voies de recours.</p>
''',
    "Réforme de fond : suppression de l'exclusivité du modèle de la DGFiP. Le modèle demeure utilisable comme aide ; un écrit exploitable contenant les données nécessaires suffit, sans recopier celles déjà disponibles. Le regroupement des déclarations reste possible sur papier comme par les voies électroniques légalement accessibles, sans imposer un nouveau portail ni une nouvelle attestation.",
    "Renvois coordonnés avec 324 AH, 324 AI et 324 AL, lequel emploie historiquement le mot formules : ce mot ne doit pas rétablir le modèle obligatoire. CGI 1502 confie au décret les conditions déclaratives ; ses conditions légales de fond ne sont pas supprimées par le choix du support. Le texte n'assimile pas tout courriel à une transmission électronique valable et ne crée pas de délai nouveau. Les formulaires administratifs correspondants devront rendre possible le dépôt regroupé et cesser d'exiger les doubles pièces.",
    removed=["Utilisation obligatoire du modèle fixé par la DGFiP et obligation de refaire une déclaration complète au seul motif d'une différence de présentation."])

add('324 AK', '''
<p>La date de référence de la première révision quinquennale des évaluations foncières des propriétés bâties est le 1er janvier 1970.</p>
''',
    "Réécriture à droit constant en énonçant directement la date de référence historique. L'article n'impose pas une nouvelle révision ni une déclaration quinquennale actuelle : cette date demeure un élément du calcul cadastral. L'abroger sans nouvelle méthode déplacerait implicitement les bases d'imposition et pourrait faire perdre une référence favorable, sans supprimer aucun prélèvement autonome.",
    "Date contrôlée : 1er janvier 1970, également reprise par 324 AL pour le loyer et les charges. Le champ de la section exclut les locaux professionnels de 1498 ; cette rédaction ne substitue donc pas 1970 à la référence professionnelle du 1er janvier 2013 lue dans 1498. Aucune date de promulgation, de réforme future ou de nouvelle révision n'est déduite de l'historique de la source.")

add('324 AL', '''
<p>I. - Les déclarations mentionnées à l'article 324 AJ contiennent les renseignements utiles à l'évaluation de chaque propriété ou fraction de propriété définie à l'article 324 A, appréciés à la date de leur souscription.</p>
<p>Toutefois, en cas de location, le montant annuel du loyer retenu est celui en vigueur au 1er janvier 1970. Les charges sont également évaluées à cette date.</p>
<p>II. - Par dérogation au premier alinéa du I, les renseignements utiles à l'évaluation d'un établissement industriel sont tirés du bilan du dernier exercice clos avant la souscription des déclarations lorsque ses immobilisations figurent à l'actif d'une entreprise industrielle ou commerciale soumise aux obligations de l'article 53 A du code général des impôts.</p>
<p>Le réemploi des données prévu aux articles 324 AH à 324 AJ n'impose pas d'établir un bilan supplémentaire. Les entreprises qui remplissent les autres conditions du II en conservent le bénéfice lorsque le seul aménagement de leurs obligations de déclaration de résultat lié à l'impôt sur les sociétés à la distribution les dispense d'une déclaration annuelle. Le renvoi à l'article 53 A n'impose par lui-même ni déclaration annuelle supplémentaire ni imposition annuelle des bénéfices conservés.</p>
<p>Le précédent alinéa s'applique à compter de l'entrée en vigueur de la loi portant la présente réforme, y compris aux évaluations en cours. Il ne modifie ni la date du 1er janvier 1970, ni la référence au dernier exercice clos applicable à l'évaluation concernée, ni les droits, restitutions, prescriptions et recours relatifs aux impositions antérieures.</p>
''',
    "Réécriture à droit constant des dates, de la référence historique des loyers et charges et de la dérogation utilisant le dernier bilan clos. Le mot déclarations remplace formules pour être compatible avec 324 AJ, sans pièce nouvelle. Coordination de fond préservant l'avantage : un simple aménagement du calendrier de déclaration résultant de l'IS à la distribution ne peut exclure du II une entreprise qui en remplit les autres conditions ; ce renvoi ne recrée ni IS annuel ni déclaration annuelle supplémentaire. Les dates et le bilan ne sont pas abrogés comme de simples survivances historiques.",
    "Source et deux subdivisions relues : le II déroge seulement au premier alinéa du I et conserve le dernier exercice clos antérieur, l'inscription des immobilisations à l'actif et les entreprises industrielles ou commerciales. CGI 53 A, annexe III 38 quinquies et CGI 1655 ter ont été lus intégralement avec leurs notes. Le premier prévoit actuellement une déclaration annuelle de résultat : la clause ajoutée empêche d'en déduire une annualité d'IS sur les bénéfices conservés ou la perte de la dérogation par la seule réforme du calendrier. La coordination législative propre de 53 A reste hors de ce lot ; son régime réel ne doit pas être confondu avec le seul paiement d'IS. Ne pas déplacer le 1er janvier 1970 vers une date courante ni utiliser un bilan futur. Coordination avec 324 AK et le réemploi de 324 AH à 324 AJ, sans modification des références d'assiette. Le champ historique de la section ne remplace pas la référence professionnelle 2013 de 1498.",
    removed=["Condition de maintien d'une déclaration annuelle de résultat pour bénéficier du II lorsque seule la réforme de l'IS à la distribution en aménage le calendrier."],
    benefit="Deux aménagements susceptibles d'être favorables sont conservés : pour une location, le loyer annuel et les charges restent appréciés au 1er janvier 1970 plutôt qu'à la date courante ; pour les établissements industriels remplissant les conditions du II, les données proviennent du dernier bilan clos, sans devoir établir un état à la date de souscription. Le premier est une référence historique d'assiette, non une exonération générale ; le second est une dérogation de date et de source documentaire. Tous deux demeurent applicables aux évaluations futures entrant dans leur champ et ne sont pas limités aux déclarations déjà déposées. Le modèle facultatif et le réemploi des données n'en conditionnent pas le bénéfice. La clause finale préserve expressément la dérogation si la seule coordination de l'IS à la distribution supprime ou aménage la déclaration annuelle de résultat de l'entreprise, sans supprimer les autres conditions ni exiger un bilan supplémentaire.")

add('328 G nonies B', '''
<p>Le présent article est abrogé pour les années d'imposition commençant à compter du 1er janvier de l'année suivant celle de l'entrée en vigueur de la loi portant la présente réforme.</p>
<p>Pour ces années, aucune répartition de valeur ajoutée entre établissements ou entre communes au prorata de la puissance électrique installée, ni aucune transmission propre à cette répartition, ne peut être exigée sur le fondement du présent article ou d'un renvoi à celui-ci. Cette disposition ne rétablit aucune cotisation sur la valeur ajoutée des entreprises ni taxe additionnelle correspondante.</p>
<p>Pour les années antérieures, les règles de répartition applicables à ces années demeurent utilisables pour l'établissement, la liquidation, le contrôle et le règlement des impositions ainsi que pour les rectifications de répartition. Les dettes légalement nées, exonérations, dégrèvements, remboursements, restitutions, prescriptions et recours sont préservés dans leurs conditions propres, même lorsque leur règlement ou leur exercice intervient après l'abrogation. Aucun remboursement général des impositions antérieures n'est institué.</p>
<p>Les sommes indûment versées au titre d'une année pour laquelle la cotisation est supprimée sont restituables dans les conditions légales de réclamation, sans exiger une nouvelle déclaration annuelle ou répartition de cette cotisation.</p>
<p>L'abrogation ne modifie ni les définitions de valeur ajoutée et de période de référence conservées pour le plafonnement de la cotisation foncière des entreprises, ni les exonérations et abattements des impositions distinctes. Les obligations légalement autonomes de ces impositions restent dans leur champ propre.</p>
''',
    "Abrogation prospective complète de la clé de répartition territoriale propre à la CVAE des établissements de production électrique concernés. La suppression de la taxe retire la raison d'être de cette répartition, tant entre établissements qu'entre communes d'un même établissement photovoltaïque. Les années anciennes gardent leurs calculs et droits ; aucun formulaire annuel futur ne peut conserver la taxe par renvoi. Il ne s'agit pas de supprimer les définitions de valeur ajoutée utiles au plafonnement de CFE ni les régimes IFER.",
    "Lecture intégrale de 328 G nonies A et de CGI 1586 octies, notamment III quatrième et cinquième alinéas : les deux proratas de puissance de la source relèvent bien de la répartition de CVAE. Coordination avec l'abrogation déjà proposée de 328 G nonies A, CGI 1586 ter et 1586 octies et les calendriers futurs, à la même date relative. Les références à CGI 1519 D et 1519 F ne suppriment pas leurs IFER distinctes. Préserver 1586 quinquies et 1586 sexies pour 1647 B sexies, ses baisses programmées de plafond, et les avantages CFE de 1600. Ni le taux ni la base de CFE ne sont modifiés ici ; ne pas assimiler la variation de CFE nette après plafonnement à une hausse de taux. Les éventuelles répartitions budgétaires autonomes hors corpus restent à identifier, sans maintenir une déclaration CVAE pour les années supprimées.",
    repeal="Suppression pour les années nouvelles des deux répartitions territoriales de valeur ajoutée au prorata de la puissance électrique installée, entre établissements puis entre communes d'un établissement photovoltaïque, exclusivement nécessaires à la CVAE supprimée.")

add('328 G decies', '''
<p>Pour l'application de l'exonération prévue à l'article 1594 I ter du code général des impôts, le prix de cession par mètre carré doit être strictement inférieur à 6 400 €. Les autres conditions prévues par cet article demeurent applicables.</p>
''',
    "Réécriture à droit constant du seuil en faisant apparaître son lien avec une exonération et le caractère strict de l'inégalité. Ce montant n'est pas une taxe ni un tarif de cession imposé : c'est le plafond réglementaire permettant l'accès à une exonération maintenue. Son abrogation isolée, alors que 1594 I ter exige un prix fixé par décret, risquerait de priver cet avantage de fondement opératoire. Aucune restriction nouvelle ni fermeture aux futures cessions éligibles n'est ajoutée.",
    "CGI 1594 I ter a été lu en entier avec sa note : faculté départementale dans les départements d'outre-mer, parts de copropriété des établissements touristiques visés, acquisition sous les anciens régimes cités, engagement hôtelier d'au moins cinq ans, rénovation, règlement (UE) 2023/2831 et prise d'effet selon 1594 E. Le présent article n'efface aucun de ces champs et n'affirme pas une conformité automatique au droit des aides d'État. Le seuil de 6 400 € demeure strict, sans indexation, seuil intermédiaire ni taux nouveau. Supprimer ou élargir la condition législative de prix exigerait une modification explicite de 1594 I ter, non une abrogation ambiguë de son décret.")

add('328 K', '''
<p>Pour l'application des articles 1519 D, 1519 E, 1519 F, 1519 G, 1519 H, 1519 HA et 1599 quater B du code général des impôts, les entreprises souscrivent la déclaration auprès du service des impôts dont relève l'installation imposée.</p>
<p>Elles choisissent un support papier ou une voie électronique légalement ouverte. Le modèle établi par l'administration est facultatif ; tout écrit exploitable comportant les renseignements légalement requis est admis. Aucun dépôt sur papier ni aucune reproduction sur le modèle administratif ne peut être exigé en plus d'une transmission valable de ces renseignements.</p>
<p>Pour une même installation, une même année d'imposition et une même situation de référence, les données exactes, suffisamment identifiées et déjà légalement détenues par le service sous une forme exploitable ne sont pas transmises de nouveau. La déclaration ne porte que sur les données manquantes et les rectifications nécessaires. Si toutes les données requises sont déjà disponibles dans ces conditions, aucun nouveau dépôt ni confirmation sans changement n'est exigé. Les éléments nécessaires à l'application d'une exonération, d'un tarif réduit ou d'une autre réduction peuvent être apportés dans les mêmes conditions, sans formalité supplémentaire créée par le présent article.</p>
<p>Les dispositions des deuxième et troisième alinéas s'appliquent aux dépôts dont l'échéance intervient à compter de l'entrée en vigueur de la loi portant la présente réforme et aux demandes de régularisation adressées après cette date dans les procédures en cours. Elles ne modifient ni les échéances légales applicables aux données restant à fournir, ni l'assiette, les tarifs et les avantages des impositions concernées, ni les droits, prescriptions et recours relatifs aux années antérieures.</p>
''',
    "Réforme de fond : fin du papier obligatoire et du modèle exclusif, suppression des doubles envois et des déclarations sans donnée nouvelle lorsque le service dispose déjà de tous les éléments exacts de l'année. La déclaration résiduelle reste limitée aux données réellement manquantes. Les sept composantes IFER demeurent à leur champ propre ; l'article ne peut abolir leurs taxes législatives par la seule disparition de leur modalité déclarative. Aucun avantage ne dépend d'une attestation nouvelle.",
    "Les sept articles législatifs cités ont été lus intégralement avec leurs notes. Préserver notamment les seuils de puissance, autoconsommation exonérée, tarifs particuliers hydrauliques et photovoltaïques, exonérations et réductions des stations radioélectriques, partage entre utilisateurs et exclusions de lignes de télécommunication. Les données réemployées doivent correspondre à l'année et à la situation imposables, non à une ancienne photographie. La dispense de renouvellement doit être expressément coordonnée avec les IV de 1519 D, E, G, H et HA, le III de 1519 F et le IV de 1599 quater B, qui posent les déclarations législatives ; une simple modification réglementaire ne les abroge pas. Leur échéance du deuxième jour ouvré suivant le 1er mai et leurs échéances spéciales de création, changement ou cessation restent applicables aux données manquantes. La note source sur 2011 n'est pas une date d'entrée en vigueur de la présente réforme. La majoration photovoltaïque programmée en 1519 F reste un prélèvement législatif à examiner séparément, non une formalité supprimée par cet article.",
    removed=[
        "Dépôt obligatoirement sur support papier et conformité obligatoire au modèle administratif pour les déclarations des sept composantes IFER visées.",
        "Nouvelle transmission, double support ou confirmation annuelle lorsque les mêmes données exactes de l'année et de la situation imposables sont déjà légalement exploitables par le service."
    ])

add('328 M', '''
<p>Pour l'application de l'article 1599 quater A du code général des impôts, les entreprises qui disposent d'un établissement sur le territoire national transmettent leur déclaration au service des impôts dont relève leur établissement principal.</p>
<p>Les entreprises sans établissement sur le territoire national transmettent leur déclaration au service des impôts des entreprises de la direction des impôts des non-résidents. Ce dépôt permet leur identification fiscale et, si nécessaire, leur immatriculation, sans demande distincte. Ce service transmet lui-même les éléments nécessaires au service des impôts dont relève l'établissement principal de la société SNCF Réseau. Aucune seconde transmission par l'entreprise n'est exigée.</p>
<p>La déclaration peut être établie, au choix de l'entreprise, sur papier ou par une voie électronique légalement ouverte. Les caractéristiques techniques et les modèles proposés par l'administration ne peuvent imposer une nouvelle transmission d'un écrit exploitable comportant tous les renseignements légalement requis. Les éléments exacts de l'année d'imposition, suffisamment identifiés et déjà légalement disponibles sous une forme exploitable sont réemployés ; seuls les éléments manquants et les rectifications sont fournis. Lorsque toutes les données requises sont ainsi disponibles, aucun nouveau dépôt ni confirmation sans changement n'est exigé.</p>
<p>Ces dispositions s'appliquent aux déclarations dont l'échéance intervient à compter de l'entrée en vigueur de la loi portant la présente réforme, ainsi qu'aux demandes d'immatriculation et de régularisation en cours à cette date. Les entreprises déjà identifiées ne demandent pas une nouvelle immatriculation. Les échéances légales pour les données restant à fournir, les règles d'imposition, les exonérations, réductions, prescriptions et recours ne sont pas modifiés.</p>
''',
    "Réforme de fond : pour les entreprises sans établissement national, un seul dépôt sert à l'identification et à la déclaration, avec transmission interne entre services. Suppression de la demande d'immatriculation séparée et du second envoi par l'entreprise, sans supprimer son identification fiscale. Le choix du support subsiste, les présentations équivalentes et le réemploi remplacent les doubles données, sans nouveau registre. Le champ de l'IFER sur le matériel roulant reste distinct de la CVAE.",
    "CGI 1599 quater A a été lu intégralement : conserver notamment les matériels exclus à la frontière, la règle d'usage principal, l'exonération sous 300 000 kilomètres et le coefficient progressif entre 300 000 et 1 700 000 kilomètres. Ne pas confondre kilomètres parcourus pour l'impôt et sillons-kilomètres réservés de 1649 A ter. Le IV de 1599 quater A doit recevoir la coordination législative du réemploi et de la dispense de redéclaration ; le présent texte ne prétend pas qu'un décret efface seul son obligation. Le service des non-résidents devient le point de dépôt unique des entreprises sans établissement, l'ancien destinataire lié à SNCF Réseau restant destinataire interne. La note de 2018 explique la dénomination de SNCF Réseau et ne fixe pas la date de la présente réforme.",
    removed=[
        "Demande distincte d'immatriculation des entreprises sans établissement national, suivie d'un envoi séparé de leur déclaration à un autre service fiscal.",
        "Répétition de données annuelles déjà légalement disponibles et rejet fondé sur la seule présentation d'une déclaration fiscalement exploitable."
    ])

add('328 N', '''
<p>La société SNCF Réseau satisfait, au plus tard le 31 mars de chaque année, à l'obligation déclarative prévue à l'article 1649 A ter du code général des impôts auprès du service de fiscalité directe locale dont relève son établissement principal. Elle peut utiliser, à son choix, un support papier ou une voie électronique légalement ouverte ; un écrit exploitable comportant les renseignements requis est admis sans reproduction obligatoire sur un modèle particulier.</p>
<p>La déclaration comporte les éléments suivants, sous réserve de leur réemploi dans les conditions du dernier alinéa :</p>
<p>1° L'identification des entreprises de transport ferroviaire ayant réservé l'année précédente des sillons-kilomètres pour des opérations de transport de voyageurs : dénomination sociale, adresse complète et numéro d'identification attribué, le cas échéant, conformément au second alinéa de l'article R. 123-221 du code de commerce ;</p>
<p>2° Le nombre de sillons-kilomètres réservés l'année précédente pour ces opérations et leur répartition par région, en précisant, pour chaque région, le nombre de sillons-kilomètres commandés par les autorités régionales conformément à l'article 1649 A ter.</p>
<p>À compter de l'entrée en vigueur de la loi portant la présente réforme, y compris pour les demandes de régularisation dans les procédures en cours, les données exactes, suffisamment identifiées et déjà légalement détenues par le service sous une forme exploitable pour l'année concernée ne sont pas transmises de nouveau. Le réemploi doit permettre le rattachement certain des quantités à chaque entreprise et région ; les éléments d'identité inchangés ne sont pas répétés lorsqu'un identifiant déjà disponible permet ce rattachement. Les seules données manquantes ou rectifications sont transmises au plus tard le 31 mars lorsqu'elles relèvent de l'échéance annuelle. Si toutes les données requises sont déjà disponibles dans ces conditions, aucun dépôt ni confirmation supplémentaire n'est exigé. Aucune déclaration déjà reçue n'est à refaire du seul fait du support utilisé ; les prescriptions et recours relatifs aux années antérieures restent préservés.</p>
''',
    "Réforme de fond : retrait du format imposé et des répétitions d'identité et de quantités déjà exploitables pour la même année. Maintien du 31 mars, des catégories de données et des subdivisions 1° et 2°. Le 2° explicite la ventilation des commandes des autorités régionales déjà exigée par la loi, mais non énoncée dans la source réglementaire ; cette coordination n'institue pas un relevé supplémentaire. Le simple maintien de la déclaration utile ne suffit pas à justifier ses copies annuelles.",
    "Lecture intégrale de CGI 1649 A ter : la source 328 N omet d'expliciter, dans son 2°, le nombre commandé par les autorités régionales dans chaque région pourtant imposé par la loi. Cette discordance préexistante est signalée et expressément coordonnée dans la proposition, sans prétendre retirer l'obligation légale. Le réemploi et la dispense de nouveau dépôt doivent également être portés dans 1649 A ter ; son renvoi aux sanctions du V de 1736 ne doit pas sanctionner une formalité supprimée par la loi de réforme. Les sillons réservés de l'année précédente ne sont pas remplacés par les kilomètres effectivement parcourus de 1599 quater A. Conservation du renvoi à R. 123-221 et de sa réserve « le cas échéant » ; la note de 2022 ne crée pas une échéance nouvelle.",
    removed=[
        "Répétition annuelle des dénominations, adresses et autres éléments d'identité déjà exploitables lorsque l'identifiant disponible permet le rattachement certain des quantités.",
        "Transmission supplémentaire de quantités et ventilations de la même année déjà légalement disponibles, et nouvelle présentation imposée pour un simple motif de format."
    ])

add('328 O', '''
<p>Pour l'application de l'article 1599 quater A bis du code général des impôts, les redevables transmettent leur déclaration au service des impôts dont relève leur établissement principal. Ils choisissent un support papier ou une voie électronique légalement ouverte. Tout écrit exploitable comportant les renseignements légalement requis est admis, sans reproduction obligatoire sur un modèle ou support supplémentaire.</p>
<p>Pour la même année d'imposition et la même situation de référence, les données exactes, suffisamment identifiées et déjà légalement disponibles sous une forme exploitable sont réemployées. Seuls les éléments manquants et les rectifications sont transmis. Lorsque toutes les données requises sont déjà disponibles dans ces conditions, aucun nouveau dépôt ni confirmation sans changement n'est exigé.</p>
<p>Ces dispositions s'appliquent aux déclarations dont l'échéance intervient à compter de l'entrée en vigueur de la loi portant la présente réforme et aux demandes de régularisation adressées après cette date dans les procédures en cours. Elles ne modifient ni l'échéance légale pour les données restant à fournir, ni l'assiette et les tarifs de l'imposition, ni les exclusions, prescriptions et recours légalement applicables.</p>
''',
    "Réforme de fond : maintien du choix papier ou électronique, mais retrait de la possibilité d'imposer une présentation supplémentaire à une déclaration exploitable. Suppression des redéclarations sans changement et limitation des envois aux lacunes et corrections. Le destinataire et le champ de l'IFER du matériel roulant des transports collectifs visés sont maintenus ; supprimer seulement cette modalité ne supprimerait pas l'impôt législatif.",
    "CGI 1599 quater A bis a été lu en entier avec sa note : propriétaire au 1er janvier, catégories de matériels, usage principal en cas de circulation sur les deux réseaux, échéance du deuxième jour ouvré suivant le 1er mai, et affectation plafonnée à la Société des grands projets restent distincts. La dispense de redéclaration doit être coordonnée expressément dans son IV pour ne pas opposer une obligation législative inchangée au réemploi prévu ici. Aucune assimilation de cette IFER à celle de 1599 quater A ni extension aux matériels de l'autre régime. La note de 2011 reste historique et ne déclenche pas la présente réforme.",
    removed=[
        "Redéclaration et confirmation sans changement lorsque les données exactes de l'année sont déjà légalement exploitables, ainsi que répétition des seules données inchangées d'une déclaration partiellement nouvelle.",
        "Reproduction obligatoire de données complètes sur un modèle ou support administratif supplémentaire alors qu'un écrit exploitable a déjà été valablement transmis."
    ])

add('328 P', '''
<p>Le propriétaire des transformateurs électriques mentionnés au III de l'article 1519 G du code général des impôts qui font l'objet d'un contrat de concession satisfait à la déclaration prévue à l'article 1649 A quater du même code auprès du service des impôts des entreprises dont relève l'installation, au plus tard le deuxième jour ouvré suivant le 1er mai de chaque année. Il choisit un support papier ou une voie électronique légalement ouverte ; un écrit exploitable comportant les renseignements requis suffit, sans reproduction obligatoire sur un modèle particulier.</p>
<p>Les renseignements nécessaires, sous réserve de leur réemploi, sont :</p>
<p>1° L'identification du concessionnaire : dénomination sociale, adresse complète et numéro d'identification attribué, le cas échéant, conformément au second alinéa de l'article R. 123-221 du code de commerce ;</p>
<p>2° Le nombre, par commune, de transformateurs électriques faisant l'objet d'un contrat de concession ;</p>
<p>3° La tension en amont de chacun de ces transformateurs.</p>
<p>Lorsque les déclarations souscrites par le concessionnaire au titre du IV de l'article 1519 G, complétées par les données déjà légalement détenues par l'administration, fournissent pour la même année et la même situation imposables tous les renseignements des 1° à 3° et permettent de les rattacher sans ambiguïté aux concessions et installations du propriétaire, l'obligation est satisfaite sans dépôt supplémentaire de celui-ci. Aucune attestation de concordance ni confirmation annuelle sans changement n'est exigée. Si seuls certains renseignements manquent ou doivent être rectifiés, la transmission du propriétaire est limitée à ces renseignements. Les données réemployées doivent être exactes, suffisamment identifiées et exploitables ; le présent article n'autorise aucun accès contraire aux secrets légalement protégés.</p>
<p>Ces dispositions s'appliquent aux déclarations dont l'échéance intervient à compter de l'entrée en vigueur de la loi portant la présente réforme et aux demandes de régularisation adressées après cette date dans les procédures en cours. Elles ne modifient ni l'échéance applicable aux renseignements restant à fournir, ni la qualité de redevable du concessionnaire, ni les règles d'assiette, les exonérations, prescriptions et recours relatifs aux impositions concernées.</p>
''',
    "Réforme de fond : suppression du double relevé du propriétaire lorsque la déclaration fiscale du concessionnaire et les données déjà détenues couvrent réellement les mêmes renseignements. Les compléments sont limités aux lacunes et erreurs, sans attestation de concordance. La présentation administrative exclusive disparaît ; les trois rubriques, le destinataire et l'échéance restent opératoires pour les cas où la donnée manque. La vérification de l'identité du redevable subsiste sans imposer deux inventaires identiques.",
    "CGI 1519 G et 1649 A quater ont été lus en entier : le concessionnaire est redevable pour les transformateurs concédés ; le IV de 1519 G demande déjà nombre par commune et tension de chaque transformateur. Le recoupement n'est pas présumé suffisant : il faut aussi l'identité et le rattachement aux concessions du propriétaire pour l'année concernée. Coordonner expressément la dispense législative dans 1649 A quater et son renvoi au VI de 1736, sans sanctionner le dépôt supprimé. Les 1°, 2° et 3°, la réserve « le cas échéant » et le deuxième jour ouvré suivant le 1er mai sont conservés. L'exonération historique de 1519 G au titre de 2010 n'est pas supprimée ni rouverte hors de son champ ; les exonérations applicables à d'autres situations restent à leur régime. La note de 2022 n'est pas une transition de la présente réforme.",
    removed=[
        "Déclaration annuelle supplémentaire du propriétaire lorsque la déclaration du concessionnaire et les données déjà détenues couvrent intégralement l'identité, le nombre par commune, la tension et le rattachement des transformateurs concédés.",
        "Attestation de concordance, confirmation sans changement et répétition des renseignements déjà exploitables lorsque seul un complément du propriétaire est nécessaire.",
        "Reproduction obligatoire sur une présentation administrative particulière après transmission valable d'un écrit contenant les renseignements nécessaires."
    ])

assert len(answers) == len(sources) == 24
Path('answer.json').write_text(json.dumps(answers, ensure_ascii=False, indent=2) + '\n')
